function calculateWorkoutMetrics(exos, reposSerie, reposExo) {
  let totalSeconds = 0;
  let totalSets = 0;
  exos.forEach((exo, idx) => {
    totalSets += exo.series;
    totalSeconds += exo.series * 40;
    totalSeconds += (exo.series - 1) * reposSerie;
    if (idx < exos.length - 1) totalSeconds += reposExo;
  });
  return { minutes: Math.max(5, Math.round(totalSeconds / 60)), calories: Math.round(totalSets * 22) };
}